/**
 * @brief Whether an edge can execute and which literal, if any, reaches it.
 */
typedef struct {
  const IrOperand* constant;
  bool reached;
} SlotFact;

/**
 * @brief Test whether two data-flow facts have the same reachability and
 * literal value.
 *
 * @param a The first fact to compare.
 * @param b The second fact to compare.
 * @return true if the facts are equivalent, false otherwise.
 */
static bool same_fact(SlotFact a, SlotFact b) {
  if (a.reached != b.reached)
    return false;

  if (a.constant == b.constant)
    return true;

  if (!a.constant || !b.constant || a.constant->type != b.constant->type)
    return false;

  switch (a.constant->type) {
    case IR_OP_INT32:
      return a.constant->value.int32_value == b.constant->value.int32_value;

    case IR_OP_DOUBLE:
      // Compare bits because +0.0 == -0.0 and NaN != NaN
      // NOLINTNEXTLINE(bugprone-suspicious-memory-comparison)
      return memcmp(&a.constant->value.double_value,
                    &b.constant->value.double_value, sizeof(IrDouble));

    case IR_OP_STRING:
      return strcmp(a.constant->value.string_value,
                    b.constant->value.string_value) == 0;

    case IR_OP_BOOL:
      return a.constant->value.bool_value == b.constant->value.bool_value;

    case IR_OP_UNIT:
      return true;

    default:
      return false;
  }
}

/**
 * @brief Join an incoming slot fact, retaining an exact value only if paths
 * agree.
 */
static void merge_fact(SlotFact* target, SlotFact incoming) {
  if (!incoming.reached)
    return;

  if (!target->reached)
    *target = incoming;
  else if (!same_fact(*target, incoming))
    target->constant = NULL;
}

/**
 * @brief Describe the exact literal or unknown value written by a store.
 */
static SlotFact stored_fact(const IrInstruction* inst) {
  const IrOperand* source = &inst->operands.store.source;

  return (SlotFact){.constant = source->type == IR_OP_VALUE ? NULL : source,
                    .reached = true};
}

bool optimizer_forward_cfg_constants(Ctx* ctx, IrFunctionId fid) {
  IrFunction* function = &ctx->ir.functions.data[fid];

  // Check if the function has at least 2 blocks and some slots
  size_t count = function->blocks.count;
  if (count < 2 || function->slots.count == 0)
    return false;

  // Keep entry, exit, and last-store facts separate. A last store overrides the
  // incoming value only on reachable paths.
  SlotFact* facts = TRY_MALLOC(count * 3 * sizeof(*facts));

  // Store pointer to the facts in the optimizer context (to be reachable in
  // case of failures)
  ctx->optimizer.cfg_facts = facts;

  SlotFact* incoming = facts;
  SlotFact* outgoing = &facts[count];
  SlotFact* local = &facts[2 * count];

  bool changed = false;

  // Go through each slot
  for (IrStackSlotId slot = 0; slot < function->slots.count; slot++) {
    // Reset facts for this slot
    memset(facts, 0, count * 3 * sizeof(*facts));

    // Go through each block and collect local store facts
    for (IrBlockId b = 0; b < count; b++) {
      IrInstructionArray* instructions = &function->blocks.data[b].instructions;

      for (size_t i = 0; i < instructions->count; i++) {
        const IrInstruction* inst = &instructions->data[i];
        if (inst->type == IR_INST_STORE && inst->operands.store.target == slot)
          local[b] = stored_fact(inst);
      }
    }

    bool progress;
    do {
      // Reset incoming facts
      memset(incoming, 0, count * sizeof(*incoming));

      // Mark the entrypoint as reached
      incoming[function->entrypoint].reached = true;

      // Propagate facts through the CFG
      for (IrBlockId b = 0; b < count; b++) {
        const IrBlockTerminator* term = &function->blocks.data[b].terminator;

        if (term->type == IR_TERMINATOR_JUMP)
          merge_fact(&incoming[term->value.jump_target], outgoing[b]);

        if (term->type == IR_TERMINATOR_CONDITIONAL) {
          merge_fact(&incoming[term->value.conditional_target.true_target],
                     outgoing[b]);
          merge_fact(&incoming[term->value.conditional_target.false_target],
                     outgoing[b]);
        }
      }

      // Merge local facts with incoming facts
      progress = false;
      for (IrBlockId b = 0; b < count; b++) {
        SlotFact next =
            incoming[b].reached && local[b].reached ? local[b] : incoming[b];

        if (!same_fact(next, outgoing[b])) {
          outgoing[b] = next;
          progress = true;
        }
      }
    } while (progress);

    // After the meet reaches a fixed point, walk each block in order to account
    // for stores before individual loads.
    for (IrBlockId b = 0; b < count; b++) {
      SlotFact current = incoming[b];
      const IrInstructionArray* instructions =
          &function->blocks.data[b].instructions;

      for (size_t instId = 0; instId < instructions->count; instId++) {
        const IrInstruction* inst = &instructions->data[instId];

        if (inst->type == IR_INST_STORE && inst->operands.store.target == slot)
          current = stored_fact(inst);

        if (current.constant && inst->type == IR_INST_LOAD &&
            inst->operands.load.source == slot && inst->result != IR_INVALID_ID)
          changed |= optimizer_replace_value(ctx, fid, inst->result,
                                             *current.constant, false) != 0;
      }
    }
  }

  // Free the facts allocated in this function
  free(ctx->optimizer.cfg_facts);
  ctx->optimizer.cfg_facts = NULL;

  return changed;
}

/**
 * @brief Compare value IDs or typed literals for expression reuse.
 *
 * @param a The first operand to compare.
 * @param b The second operand to compare.
 * @return true if the operands are equivalent, false otherwise.
 */
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Share repeated loads and non-faulting expressions within a block.
static bool equivalent_operand(const IrOperand* a, const IrOperand* b) {
  if (a->type == IR_OP_VALUE && b->type == IR_OP_VALUE)
    return a->value.id == b->value.id;

  return same_fact((SlotFact){a, true}, (SlotFact){b, true});
}

/**
 * @brief Check whether two eligible instructions compute the same result.
 *
 * @param a The first instruction to compare.
 * @param b The second instruction to compare.
 * @return true if the instructions are equivalent, false otherwise.
 */
static bool equivalent_expression(IrInstruction* a, IrInstruction* b) {
  if (a->type != b->type || a->result_type != b->result_type)
    return false;

  switch (ir_get_instruction_class(a)) {
    case IR_INST_CLASS_UNARY:
      return a->type != IR_INST_FLOOR &&
             equivalent_operand(&a->operands.unary.operand,
                                &b->operands.unary.operand);

    case IR_INST_CLASS_BINARY:
      return a->type != IR_INST_DIV && a->type != IR_INST_IDIV &&
             equivalent_operand(&a->operands.binary.left,
                                &b->operands.binary.left) &&
             equivalent_operand(&a->operands.binary.right,
                                &b->operands.binary.right);

    case IR_INST_CLASS_LOAD:
      return a->operands.load.source == b->operands.load.source;

    default:
      return false;
  }
}

bool optimizer_reuse_expressions(Ctx* ctx, IrFunctionId fid) {
  IrFunction* function = &ctx->ir.functions.data[fid];

  bool changed = false;

  // Iterate over each instruction in each block
  for (IrBlockId bid = 0; bid < function->blocks.count; bid++) {
    IrInstructionArray* instructions = &function->blocks.data[bid].instructions;
    for (size_t inst_id = 1; inst_id < instructions->count; inst_id++) {
      IrInstruction* inst = &instructions->data[inst_id];

      if (inst->result == IR_INVALID_ID || inst->type == IR_INST_CALL)
        continue;

      // Limit the scan in very large straight-line blocks.
      size_t first = inst_id > 32 ? inst_id - 32 : 0;
      for (size_t j = inst_id; j > first;) {
        IrInstruction* prior = &instructions->data[--j];
        if (inst->type == IR_INST_LOAD && prior->type == IR_INST_STORE &&
            inst->operands.load.source == prior->operands.store.target)
          break;

        if (prior->result == IR_INVALID_ID ||
            !equivalent_expression(inst, prior))
          continue;

        // If the instructions are equivalent, replace the current one with the
        // prior one
        optimizer_replace_value(ctx, fid, inst->result,
                                (IrOperand){IR_OP_VALUE, {.id = prior->result}},
                                false);

        ir_free_instruction(inst);
        array_remove(ctx, instructions, inst_id);
        inst_id--;

        changed = true;

        break;
      }
    }
  }

  return changed;
}
